SELECT ROUND(SUM(amount)::numeric, 2) AS total_collected_this_year
FROM public_payment_details
WHERE EXTRACT(YEAR FROM pay_date) = EXTRACT(YEAR FROM CURRENT_DATE);

SELECT ROUND(AVG(net_price)::numeric, 2) AS avg_paid_bag_net_price
FROM public_academic_bag
WHERE payment_status = 3;

SELECT
  ROUND(SUM(amount) FILTER (
    WHERE pay_date >= DATE_TRUNC('quarter', CURRENT_DATE)
      AND pay_date <  DATE_TRUNC('quarter', CURRENT_DATE) + INTERVAL '3 months'
  )::numeric, 2) AS this_quarter,
  ROUND(SUM(amount) FILTER (
    WHERE pay_date >= DATE_TRUNC('quarter', CURRENT_DATE) - INTERVAL '3 months'
      AND pay_date <  DATE_TRUNC('quarter', CURRENT_DATE)
  )::numeric, 2) AS last_quarter
FROM public_payment_details;

