SELECT COUNT(*) AS active_order_count
FROM public_logistics_orders
WHERE is_active = true;

SELECT ROUND(SUM(total_amount)::numeric, 2) AS total_order_amount_this_year
FROM public_logistics_orders
WHERE EXTRACT(YEAR FROM created_at) = EXTRACT(YEAR FROM CURRENT_DATE);

SELECT ROUND(AVG(shipment_fee_amount)::numeric, 2) AS avg_shipment_fee
FROM public_logistics_orders
WHERE is_active = true;

SELECT ROUND(AVG(month_total)::numeric, 2) AS avg_of_monthly_totals
FROM (
  SELECT DATE_TRUNC('month', created_at) AS month, SUM(total_amount) AS month_total
  FROM public_logistics_orders
  GROUP BY DATE_TRUNC('month', created_at)
) monthly;

SELECT
  ROUND(SUM(total_amount) FILTER (
    WHERE created_at >= DATE_TRUNC('quarter', CURRENT_DATE)
      AND created_at <  DATE_TRUNC('quarter', CURRENT_DATE) + INTERVAL '3 months'
  )::numeric, 2) AS this_quarter,
  ROUND(SUM(total_amount) FILTER (
    WHERE created_at >= DATE_TRUNC('quarter', CURRENT_DATE) - INTERVAL '3 months'
      AND created_at <  DATE_TRUNC('quarter', CURRENT_DATE)
  )::numeric, 2) AS last_quarter
FROM public_logistics_orders;
